function moreProduct(t){t.preventDefault();const n=document.querySelector("#header-main-menu");const e=n.querySelector("a.active");var r="nam";if(e){r=e.getAttribute("data-value")}var o=t.currentTarget.href+"&c="+r+"&page="+t.currentTarget.getAttribute("data-value");getProductList(o).then((function(t){renderProductList(t)})).catch((function(t){showErrorToast2("Có lỗi khi lấy sản phẩm","none")}))}function updateMorePage(t){const n=document.querySelector("#btn-more-product");var e=n.getAttribute("data-value");if(e==t){showInfoToast2("Đã tới cuối trang","none")}else{n.setAttribute("data-value",t)}}function renderProductList(t){var n=t.productUnits;var e=t.script;const r=$("#product-list");console.log("vo vong lap");n.forEach((function(t){var n=t.product;var e="";var o=t.saleProgram;if(o.title!==undefined){e=`\n                <div class="info promotion">\n                    <p class="promotion-item">${o.title}</p>\n                </div>\n            `}const i=`\n             <div class="grid-col-2_4 product-item-container grid-col-4_tab grid-col-6_mob">\n                <div class="product-item product-item_mob">\n                    <a href="product?a=detail&id=${n.id}">\n                        <div class="img-container flex-roww" style="justify-content: center;">\n                            <img class="img-product" src="./assets/img/thumbnail/${n.thumbnail}" alt="${n.name}">\n                        </div>\n                        ${e}\n                        <div class="info name info-name_mob">\n                            <p>${n.name}</p>\n                        </div>\n                        <div class="price" style="margin-top: 0;">\n                            <div><p class="cur-price">${t.formatPrice}</p> </div>\n                            <div class="flex-roww flex-coll_mob" style="justify-content: space-between;">\n                                <p class="pre-price">${t.formatPrePrice}</p>\n                                <div class="info rate">\n                                    <p><i class="bi bi-star-fill"></i><span class="rate-figure">${t.star}</span>(<span class="total-estimate">${t.totalComment}</span>)</p>\n                                </div>\n                            </div>\n                        </div>\n                    </a>\n\n\n                </div>\n\n            </div>\n        `;r.append(i)}));$("#product-response").html(e)}function getProductList(t){console.log("getProductList");return new Promise(((n,e)=>{$.ajax({url:t,type:"GET",dataType:"json",success:function(t){console.log(t);n(t)},error:function(t){e(t)}})}))}